// Parser for V8's `--print-bytecode` textual listing.
//
// The format is produced by BytecodeArray::Disassemble (src/objects/bytecode-
// array.cc) + BytecodeDecoder::Decode (src/interpreter/bytecode-decoder.cc) and
// has been stable for many V8 versions. One listing per compiled function:
//
//   [generated bytecode for function: f (0x01e40101d529 <SharedFunctionInfo f>)]
//   Bytecode length: 59
//   Parameter count 3
//   Register count 5
//   Frame size 40
//      19 S> 0x101000104 @    0 : 87 00 00 29       CreateObjectLiteral [0:...], FBV[0], #29
//             0x101000108 @    4 : d2                Star0
//   Constant pool (size = 5)
//   [optional pool dump -- only when the engine was built with object printing]
//   Handler Table (size = 32)
//      from   to       hdlr (prediction,   data)
//     (   5,  39)  ->    39 (prediction=0, data=3)
//   Source Position Table (size = 10)
//   [optional address line]
//
// Two engine-dependent differences the parser absorbs:
//   * the address column is `0x101000104` (d8, %p on posix-style printf) or
//     `0000023E7EE330C8` (node on Windows) -- both are incidental.
//   * d8 release builds print only `Constant pool (size = N)`; node prints the
//     whole pool. The inline `[index:value]` annotations are present in both,
//     so the pool is reconstructed from those and marked `partial` when the
//     dump is missing.

/** One instruction line. */
const INSTR_RE = new RegExp(
  '^' +
  // 1 source position, 2 marker. BytecodeArray::Disassemble prints
  //   " S> "  statement + breakable      " s> "  statement, not breakable
  //   " E> "  expression + breakable     " e> "  expression, not breakable
  // (src/objects/bytecode-array.cc, is_statement() x is_breakable()).
  '(?:\\s*(\\d+)\\s+([SsEe])>)?' +
  '\\s+((?:0x)?[0-9A-Fa-f]{4,})' +          // 3 address (incidental)
  '\\s+@\\s+(\\d+)\\s+:\\s+' +              // 4 bytecode offset
  '((?:[0-9a-f]{2} )*[0-9a-f]{2})' +        // 5 raw bytes
  '(?:\\s+(\\S.*?))?' +                     // 6 mnemonic + operands
  '\\s*$'
);

const HEADER_RE = /^\[generated bytecode for function:\s*(.*?)\s*\((?:0x)?[0-9A-Fa-f]+\s*<SharedFunctionInfo(?:\s+(.*?))?>\)\]$/;
const POOL_RE = /^Constant pool \(size = (\d+)\)$/;
const HANDLER_RE = /^Handler Table \(size = (\d+)\)$/;
const SRCPOS_RE = /^Source Position Table \(size = (\d+)\)$/;
const POOL_ENTRY_RE = /^\s*(\d+):\s*(.*?)\s*$/;
const HANDLER_ENTRY_RE = /^\s*\(\s*(\d+),\s*(\d+)\)\s*->\s*(\d+)\s*\(prediction=(\d+),\s*data=(-?\d+)\)\s*$/;

// The operand vocabulary is shared with the renderer in src/disasm/format.mjs,
// so it lives in src/listing/ rather than here; re-exported because every
// existing importer asks this module for it.
import {
  stripAddress, splitOperands, parseOperand, renderOperand,
} from '../listing/operands.mjs';

export { stripAddress, splitOperands, parseOperand, renderOperand };

/**
 * Pull the two trailing annotations V8 appends after the real operands:
 *   `(0x... @ 32)`   resolved jump target
 *   `{ 0: @57, 1: @60 }`  jump table targets
 */
function extractAnnotations(operandText) {
  let text = operandText;
  let jumpTable = null, jumpTarget = null;
  const tableM = /\s*\{([^{}]*)\}\s*$/.exec(text);
  if (tableM) {
    jumpTable = [];
    for (const e of tableM[1].matchAll(/(-?\d+)\s*:\s*@(\d+)/g)) jumpTable.push({ caseValue: +e[1], target: +e[2] });
    text = text.slice(0, tableM.index);
  }
  const targetM = /\s*\((?:0x)?[0-9A-Fa-f]+\s+@\s+(\d+)\)\s*$/.exec(text);
  if (targetM) { jumpTarget = +targetM[1]; text = text.slice(0, targetM.index); }
  return { text: text.trim(), jumpTarget, jumpTable };
}

function parseInstructionLine(line) {
  const m = INSTR_RE.exec(line);
  if (!m) return null;
  const [, srcPos, marker, address, offset, bytesHex, tail] = m;
  let mnemonic = null, operandText = '';
  if (tail) {
    const sp = tail.indexOf(' ');
    if (sp < 0) mnemonic = tail;
    else { mnemonic = tail.slice(0, sp); operandText = tail.slice(sp + 1).trim(); }
  }
  let scale = null;
  if (mnemonic && /\.(Wide|ExtraWide)$/.test(mnemonic)) {
    const i = mnemonic.lastIndexOf('.');
    scale = mnemonic.slice(i + 1);
    mnemonic = mnemonic.slice(0, i);
  }
  const ann = extractAnnotations(operandText);
  const operands = ann.text ? splitOperands(ann.text).map(parseOperand) : [];
  return {
    raw: line,
    sourcePosition: srcPos != null ? +srcPos : null,
    isStatement: marker === 'S' || marker === 's',
    isExpression: marker === 'E' || marker === 'e',
    isBreakable: marker === 'S' || marker === 'E',
    address,
    offset: +offset,
    bytes: bytesHex.split(' ').map((h) => parseInt(h, 16)),
    opcode: mnemonic,
    scale,
    operands,
    jumpTarget: ann.jumpTarget,
    jumpTable: ann.jumpTable,
    operandText: ann.text,
  };
}

/** Rebuild the semantic part of an instruction line (for round-trip testing). */
export function renderInstruction(ins) {
  const parts = [];
  parts.push(`@${ins.offset}`);
  parts.push(':');
  parts.push(ins.bytes.map((b) => b.toString(16).padStart(2, '0')).join(' '));
  parts.push(ins.opcode + (ins.scale ? '.' + ins.scale : ''));
  const ops = ins.operands.map(renderOperand).join(', ');
  if (ops) parts.push(ops);
  if (ins.jumpTarget != null) parts.push(`(@ ${ins.jumpTarget})`);
  if (ins.jumpTable) parts.push(`{ ${ins.jumpTable.map((e) => `${e.caseValue}: @${e.target}`).join(', ')} }`);
  return parts.join(' ');
}

/** The same shape, extracted straight from the raw line -- the round-trip oracle. */
export function canonicalizeRawLine(raw) {
  const m = INSTR_RE.exec(raw);
  if (!m) return null;
  const [, , , , offset, bytesHex, tail] = m;
  const parts = [`@${+offset}`, ':', bytesHex];
  if (tail) {
    const sp = tail.indexOf(' ');
    const mn = sp < 0 ? tail : tail.slice(0, sp);
    parts.push(mn);
    if (sp >= 0) {
      let rest = tail.slice(sp + 1).trim();
      const tableM = /\s*\{([^{}]*)\}\s*$/.exec(rest);
      let table = null;
      if (tableM) { table = tableM[1]; rest = rest.slice(0, tableM.index).trim(); }
      const targetM = /\s*\((?:0x)?[0-9A-Fa-f]+\s+@\s+(\d+)\)\s*$/.exec(rest);
      let target = null;
      if (targetM) { target = +targetM[1]; rest = rest.slice(0, targetM.index).trim(); }
      if (rest) parts.push(splitOperands(rest).join(', '));
      if (target != null) parts.push(`(@ ${target})`);
      if (table != null) {
        const entries = [...table.matchAll(/(-?\d+)\s*:\s*@(\d+)/g)].map((e) => `${+e[1]}: @${+e[2]}`);
        parts.push(`{ ${entries.join(', ')} }`);
      }
    }
  }
  return parts.join(' ');
}

/**
 * Parse a whole `--print-bytecode` dump.
 * @returns {{functions: Array, unparsedLines: string[]}}
 */
export function parseBytecodeDump(text) {
  const lines = text.split(/\r?\n/);
  const functions = [];
  const unparsedLines = [];
  let fn = null;
  let section = null;

  const flush = () => { if (fn) functions.push(fn); fn = null; section = null; };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim() === '') continue;

    const h = HEADER_RE.exec(line.trim());
    if (h) {
      flush();
      fn = {
        name: (h[2] ?? h[1] ?? '').trim(),
        headerName: h[1] ?? '',
        bytecodeLength: null,
        parameterCount: null,
        registerCount: null,
        frameSize: null,
        instructions: [],
        constantPool: [],
        constantPoolSize: null,
        constantPoolResolution: 'partial',
        handlerTable: [],
        handlerTableSize: null,
        sourcePositionTableSize: null,
      };
      section = 'header';
      continue;
    }
    if (!fn) { if (line.trim()) unparsedLines.push(line); continue; }

    let m;
    if ((m = /^Bytecode length:\s*(\d+)$/.exec(line.trim()))) { fn.bytecodeLength = +m[1]; continue; }
    if ((m = /^Parameter count\s*(\d+)$/.exec(line.trim()))) { fn.parameterCount = +m[1]; continue; }
    if ((m = /^Register count\s*(\d+)$/.exec(line.trim()))) { fn.registerCount = +m[1]; continue; }
    if ((m = /^Frame size\s*(\d+)$/.exec(line.trim()))) { fn.frameSize = +m[1]; continue; }
    if ((m = POOL_RE.exec(line.trim()))) { fn.constantPoolSize = +m[1]; section = 'pool'; continue; }
    if ((m = HANDLER_RE.exec(line.trim()))) { fn.handlerTableSize = +m[1]; section = 'handlers'; continue; }
    if ((m = SRCPOS_RE.exec(line.trim()))) { fn.sourcePositionTableSize = +m[1]; section = 'srcpos'; continue; }

    if (section === 'header' || section === null) {
      const ins = parseInstructionLine(line);
      if (ins) { fn.instructions.push(ins); continue; }
      unparsedLines.push(line);
      continue;
    }
    if (section === 'pool') {
      // `           3: 0x002ae45c5639 <String[1]: #d>`  or  `           0: 8`
      const e = POOL_ENTRY_RE.exec(line);
      if (e && !/^\s*-\s/.test(line) && !/\[TrustedFixedArray\]/.test(line)) {
        fn.constantPool[+e[1]] = { index: +e[1], value: stripAddress(e[2]), raw: e[2] };
        fn.constantPoolResolution = 'dumped';
        continue;
      }
      continue; // `: [TrustedFixedArray]`, ` - map: ...`, ` - length: N`
    }
    if (section === 'handlers') {
      const e = HANDLER_ENTRY_RE.exec(line);
      if (e) { fn.handlerTable.push({ from: +e[1], to: +e[2], handler: +e[3], prediction: +e[4], data: +e[5] }); continue; }
      continue; // the `from to hdlr (prediction, data)` title row
    }
    // section === 'srcpos': a lone address line, nothing structured
  }
  flush();

  // Fill in whatever the inline `[index:value]` annotations told us about the
  // constant pool for engines that do not dump it.
  for (const f of functions) {
    for (const ins of f.instructions) {
      for (const op of ins.operands) {
        if (op.kind === 'constant' && f.constantPool[op.index] === undefined) {
          f.constantPool[op.index] = { index: op.index, value: stripAddress(op.value), raw: op.value, from: 'inline' };
        }
      }
    }
    if (f.constantPoolSize != null) {
      for (let i = 0; i < f.constantPoolSize; i++) if (f.constantPool[i] === undefined) f.constantPool[i] = null;
    }
  }
  return { functions, unparsedLines };
}

export { INSTR_RE, parseInstructionLine };
